let lang='fa';
function get(obj,path){return path.split('.').reduce((a,k)=>a?.[k],obj)}
function applyLang(l){lang=l;const t=translations[l];document.documentElement.lang=l;document.documentElement.dir=l==='en'?'ltr':'rtl';document.title=l==='fa'?'مهر آذین پک | طراحی، چاپ و تولید بسته‌بندی':l==='en'?'Mehr Azin Pack | Packaging Design & Production':'مهر آذین باك | تصميم وإنتاج التغليف';document.querySelectorAll('[data-i18n]').forEach(el=>{const v=get(t,el.dataset.i18n);if(v!=null)el.innerHTML=v});document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{const v=get(t,el.dataset.i18nPlaceholder);if(v!=null)el.placeholder=v});document.querySelectorAll('.lang').forEach(b=>b.classList.toggle('active',b.dataset.lang===l));}


document.addEventListener('DOMContentLoaded',()=>{
  document.querySelectorAll('.lang').forEach(b=>{
    b.addEventListener('click',()=>applyLang(b.dataset.lang));
  });

  const menuBtn=document.getElementById('menuBtn');
  const nav=document.getElementById('mainNav');

  if(menuBtn && nav){
    menuBtn.addEventListener('click',()=>{
      const open=nav.classList.toggle('open');
      menuBtn.setAttribute('aria-expanded',String(open));
      menuBtn.setAttribute('aria-label',open?'بستن منو':'باز کردن منو');
    });
    nav.querySelectorAll('a').forEach(a=>{
      a.addEventListener('click',()=>{
        nav.classList.remove('open');
        menuBtn.setAttribute('aria-expanded','false');
        menuBtn.setAttribute('aria-label','باز کردن منو');
      });
    });
  }

  const modal=document.getElementById('modal');
  const modalImg=document.getElementById('modalImg');
  const modalTitle=document.getElementById('modalTitle');
  const modalText=document.getElementById('modalText');
  const modalNum=document.getElementById('modalNum');

  const closeModal=()=>{
    if(!modal) return;
    modal.classList.remove('open');
    modal.setAttribute('aria-hidden','true');
    document.body.classList.remove('modal-open');
    if(modalImg) modalImg.src='';
  };

  const openModal=()=>{
    if(!modal) return;
    modal.classList.add('open');
    modal.setAttribute('aria-hidden','false');
    document.body.classList.add('modal-open');
  };

  const productData={
    boxes:['01','products.box.title','products.box.text'],
    bags:['02','products.bag.title','products.bag.text'],
    handles:['03','products.handle.title','products.handle.text'],
    ribbons:['04','products.ribbon.title','products.ribbon.text']
  };

  document.querySelectorAll('[data-open]').forEach(b=>{
    b.addEventListener('click',()=>{
      const d=productData[b.dataset.open];
      if(!d || !modal) return;
      const img=b.closest('.product-card')?.querySelector('img');
      if(modalImg && img) modalImg.src=img.currentSrc || img.src;
      if(modalNum) modalNum.textContent=d[0];
      if(modalTitle) modalTitle.innerHTML=get(translations[lang],d[1]) || '';
      if(modalText) modalText.innerHTML=get(translations[lang],d[2]) || '';
      openModal();
    });
  });

  document.querySelectorAll('[data-close]').forEach(x=>{
    x.addEventListener('click',closeModal);
  });

  // Portfolio slider: autoplay + manual controls + dots + keyboard + pause on hover/focus.
  const portfolioSlider=document.getElementById('portfolioSlider');
  if(portfolioSlider){
    const slides=[...portfolioSlider.querySelectorAll('.portfolio-slide')];
    const dots=[...portfolioSlider.querySelectorAll('.portfolio-dot')];
    const prevBtn=portfolioSlider.querySelector('.portfolio-prev');
    const nextBtn=portfolioSlider.querySelector('.portfolio-next');
    const currentEl=document.getElementById('portfolioCurrent');
    let current=0;
    let autoplay=null;
    const delay=4500;

    const showSlide=(index)=>{
      if(!slides.length) return;
      current=(index+slides.length)%slides.length;
      slides.forEach((slide,i)=>slide.classList.toggle('active',i===current));
      dots.forEach((dot,i)=>{
        const active=i===current;
        dot.classList.toggle('active',active);
        dot.setAttribute('aria-selected',active?'true':'false');
      });
      if(currentEl) currentEl.textContent=String(current+1).padStart(2,'0');
    };

    const startAutoplay=()=>{
      clearInterval(autoplay);
      if(window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
      autoplay=setInterval(()=>showSlide(current+1),delay);
    };
    const stopAutoplay=()=>clearInterval(autoplay);

    prevBtn?.addEventListener('click',()=>{
      showSlide(current-1);
      startAutoplay();
    });
    nextBtn?.addEventListener('click',()=>{
      showSlide(current+1);
      startAutoplay();
    });
    dots.forEach((dot,i)=>{
      dot.addEventListener('click',()=>{
        showSlide(i);
        startAutoplay();
      });
    });

    // Autoplay continues even while the mouse is over the slider.
    // It only pauses while the slider has keyboard focus.
    portfolioSlider.addEventListener('focusin',stopAutoplay);
    portfolioSlider.addEventListener('focusout',e=>{
      if(!portfolioSlider.contains(e.relatedTarget)) startAutoplay();
    });
    portfolioSlider.addEventListener('keydown',e=>{
      if(e.key==='ArrowRight'){
        e.preventDefault();
        showSlide(current-1);
        startAutoplay();
      }else if(e.key==='ArrowLeft'){
        e.preventDefault();
        showSlide(current+1);
        startAutoplay();
      }
    });

    // Clicking the active image opens the existing modal at full size.
    slides.forEach((slide)=>{
      slide.addEventListener('click',()=>{
        if(!modal) return;
        const img=slide.querySelector('img');
        if(modalImg) modalImg.src=img?.currentSrc || img?.src || '';
        if(modalNum) modalNum.textContent='';
        if(modalTitle) modalTitle.textContent=`نمونه‌کار ${current+1}`;
        if(modalText) modalText.textContent='';
        openModal();
      });
    });

    showSlide(0);
    startAutoplay();
  }

  document.addEventListener('keydown',e=>{
    if(e.key==='Escape') closeModal();
  });

  // Reliable back-to-top: do not rely solely on the browser's anchor handling.
  const backToTop=document.getElementById('backToTop');
  if(backToTop){
    backToTop.addEventListener('click',e=>{
      e.preventDefault();
      window.scrollTo({top:0,left:0,behavior:'smooth'});
      history.replaceState(null,'','#top');
    });
  }

  // Reveal animation with a safe fallback if IntersectionObserver is unavailable.
  const revealItems=document.querySelectorAll('.reveal');
  if('IntersectionObserver' in window){
    const observer=new IntersectionObserver(entries=>{
      entries.forEach(entry=>{
        if(entry.isIntersecting){
          entry.target.classList.add('visible');
          observer.unobserve(entry.target);
        }
      });
    },{threshold:.08,rootMargin:'0px 0px -30px 0px'});
    revealItems.forEach(el=>observer.observe(el));
  }else{
    revealItems.forEach(el=>el.classList.add('visible'));
  }

  // Keep the header state correct if the page is loaded with a hash.
  if(location.hash){
    requestAnimationFrame(()=>{
      const target=document.querySelector(location.hash);
      if(target) target.scrollIntoView({behavior:'auto',block:'start'});
    });
  }

  applyLang('fa');
});


/* Premium customer-club hover: preserve the exact marquee position, then pause. */
document.addEventListener('DOMContentLoaded', () => {
  const marquee = document.querySelector('.logo-marquee');
  if (!marquee) return;
  let pauseTimer;

  marquee.addEventListener('mouseenter', () => {
    clearTimeout(pauseTimer);
    marquee.classList.add('is-hovering');
    pauseTimer = setTimeout(() => marquee.classList.add('is-paused'), 1050);
  });

  marquee.addEventListener('mouseleave', () => {
    clearTimeout(pauseTimer);
    marquee.classList.remove('is-paused');
    requestAnimationFrame(() => marquee.classList.remove('is-hovering'));
  });
});
